  | C_TcErr_IntStringCaseRestriction -> "case on Int / String accepts only literal or variable patterns"
  | C_TcErr_IntStringCaseNeedsFallback -> "case on Int / String needs a variable or wildcard fallback branch"
  | C_TcErr_NoInstParam -> "the @ override requires an implicit String instance parameter"
  | C_TcErr_InterfaceNoParam -> "interfaces must have at least one parameter"
  | C_TcErr_OrphanInstance -> "orphan instance: declare it in the trait or head type module"
  | C_TcErr_InstanceMissingMethod -> "instance is missing an interface method implementation"
  | C_TcErr_ConstraintNotDict -> "constraint must be an interface application (e.g. Eq a, Convert a b)"
  | C_TcErr_InstanceHeadNotApp -> "instance head must be an interface application (e.g. Show Int)"
  | C_TcErr_IndexFuel -> "index unification ran out of reduction fuel"
  | C_TcErr_ImpossibleBranchIndex -> "branch is impossible (index constraints are unsatisfiable)"
  | C_TcErr_ImpossibleBranchEmptyCtx -> "branch is impossible (its context contains an empty inductive family)"
  | C_TcErr_ImplicitParamKind -> "implicit parameters must be types or inductive families"
  | C_TcErr_HoleNoExpectedType -> "cannot infer the type of a hole without an expected type"
  | C_TcErr_FunctionNoClauses -> "function has no clauses"
  | C_TcErr_DoUnsupported -> "do block must be lowered to bind applications before elaboration"
  | C_TcErr_DefParamsMustBeVars -> "definition parameters must be variables"
  | C_TcErr_DefMoreParams -> "definition has more parameters than its signature"
  | C_TcErr_DataKindArrows -> "data declaration kind must be a chain of arrows ending in Type"
  | C_TcErr_ClauseTooManyPatterns -> "clause has more patterns than the function arity"
  | C_TcErr_CatchAllNotLast -> "catch-all branch must come last"
  | C_TcErr_CaptureFuel -> "linear capture check ran out of reduction fuel (program rejected conservatively)"
  | C_TcErr_CaseBranchTooFewArgs (dtb_u_u179, dtb_u_u180) -> "case branch for constructor <0> is missing fields: <1>"
  | C_TcErr_BoolCaseRestriction -> "case on Bool accepts only True, False, or variable patterns"
  | _ -> failwith "DT: impossible branch"
))

